import{_ as o,o as a,c as t,a2 as r}from"./chunks/framework.Wk4ah3nE.js";const m=JSON.parse('{"title":"Changelog","description":"Release history for Proxmox VM Autoscale, including behaviour changes that affect existing installations.","frontmatter":{"title":"Changelog","description":"Release history for Proxmox VM Autoscale, including behaviour changes that affect existing installations.","head":[["link",{"rel":"canonical","href":"https://fabriziosalmi.github.io/proxmox-vm-autoscale/reference/changelog.html"}],["meta",{"property":"og:url","content":"https://fabriziosalmi.github.io/proxmox-vm-autoscale/reference/changelog.html"}],["meta",{"property":"og:title","content":"Changelog"}],["meta",{"property":"og:description","content":"Release history for Proxmox VM Autoscale, including behaviour changes that affect existing installations."}]]},"headers":[],"relativePath":"reference/changelog.md","filePath":"reference/changelog.md","lastUpdated":null}'),i={name:"reference/changelog.md"};function n(d,e,c,s,l,h){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>Maintained in <a href="https://github.com/fabriziosalmi/proxmox-vm-autoscale/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer"><code>CHANGELOG.md</code></a>, following <a href="https://keepachangelog.com/en/1.0.0/" target="_blank" rel="noreferrer">Keep a Changelog</a>.</p><div class="warning custom-block"><p class="custom-block-title">Tags are not in chronological order</p><p><code>v1.2.0</code> was published in December 2025 and <code>v0.1.1</code> in April 2026 — and <strong><code>v0.1.1</code> is the current release</strong>. The version numbers do not reflect ordering. Go by <a href="https://github.com/fabriziosalmi/proxmox-vm-autoscale/releases" target="_blank" rel="noreferrer">the releases page</a> rather than by the highest number.</p></div><h2 id="unreleased" tabindex="-1">Unreleased <a class="header-anchor" href="#unreleased" aria-label="Permalink to &quot;Unreleased&quot;">​</a></h2><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><p><strong><code>scaling_limits</code> from <code>config.yaml</code> is now actually enforced.</strong> The validator required the section, but the code looked its values up as flat top-level keys under names that do not exist (<code>max_ram</code>/<code>min_ram</code> instead of <code>max_ram_mb</code>/<code>min_ram_mb</code>). Every installation silently ran on the hardcoded defaults 1–8 cores and 512–16384 MB, so the documented <code>min_ram_mb: 1024</code> — needed because NUMA misbehaves below 1 GB — had no effect. Flat keys remain accepted as a fallback for older configs.</p><div class="danger custom-block"><p class="custom-block-title">Upgrade note</p><p>Your configured limits are about to take effect for the first time. Re-read <code>scaling_limits</code> before upgrading, particularly if you set a <code>max_cores</code> above 8 or a <code>min_ram_mb</code> above 512 and have been running against the defaults without realising.</p></div></li><li><p><strong>CPU and RAM now have independent cooldowns</strong> (<a href="https://github.com/fabriziosalmi/proxmox-vm-autoscale/issues/30" target="_blank" rel="noreferrer">#30</a>). A single shared timestamp meant any CPU threshold breach suppressed RAM scaling for the same cycle. The cooldown is also consumed only when a scaling command is actually issued — previously the <em>check</em> consumed it, so a VM already at its limit was rate-limited for doing nothing.</p></li><li><p><strong><code>scale_cooldown</code> now applies between polling cycles.</strong> <code>VMResourceManager</code> was rebuilt on every iteration of the main loop, resetting the cooldown to zero; the effective interval was <code>check_interval</code>, not <code>scale_cooldown</code>. Managers are now cached per VM and rebound to each cycle&#39;s SSH connection. Side effect: hotplug auto-configuration runs once per VM instead of two extra <code>qm config</code> calls per VM per cycle.</p></li></ul><h3 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h3><ul><li><strong><code>install.sh</code> no longer leaves <code>config.yaml</code> world-readable.</strong> A recursive <code>chmod 755</code> over the install directory applied to the config file too — the file holding the Proxmox root SSH password and SMTP credentials in plain text. The config and its backup are now root-owned mode <code>600</code>, and the backup directory mode <code>700</code>, matching what <code>SECURITY.md</code> already prescribed.</li></ul><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><code>tests/test_scaling_limits_and_cooldown.py</code>: 20 regression tests covering limit resolution (including one asserting the limits shipped in <code>config.yaml</code> are the ones enforced), independent per-resource cooldowns, and manager reuse across cycles.</li><li>This documentation site.</li></ul><h2 id="_0-1-1-—-2026-04-27" tabindex="-1">[0.1.1] — 2026-04-27 <a class="header-anchor" href="#_0-1-1-—-2026-04-27" aria-label="Permalink to &quot;[0.1.1] — 2026-04-27&quot;">​</a></h2><h3 id="fixed-1" tabindex="-1">Fixed <a class="header-anchor" href="#fixed-1" aria-label="Permalink to &quot;Fixed&quot;">​</a></h3><ul><li><strong>Host RAM usage now matches the Proxmox web UI</strong> (<a href="https://github.com/fabriziosalmi/proxmox-vm-autoscale/issues/38" target="_blank" rel="noreferrer">#38</a>). RAM was computed from <code>free + cached</code>, ignoring reclaimable buff/cache, so a host with a warm page cache reported ~90% usage when the real figure was ~66% — and all scaling on it was suppressed. It now reads the <code>used</code> field from <code>pvesh</code> directly.</li></ul><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to &quot;Added&quot;">​</a></h3><ul><li><code>tests/test_host_resource_checker.py</code> — full coverage of <code>HostResourceChecker</code>: the RAM fix, threshold boundaries, byte-valued output, error paths.</li><li><code>tests/test_autoscale.py</code> — <code>NotificationManager</code> validation, formatting and routing; <code>VMAutoscaler</code> config loading; CPU/RAM decision logic; <code>VMResourceManager</code> scaling helpers.</li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to &quot;Changed&quot;">​</a></h3><ul><li>Removed unused <code>cached_mem</code> and <code>free_mem</code> variables from <code>HostResourceChecker</code>.</li></ul><h2 id="_1-2-0-—-2025-12-09" tabindex="-1">[1.2.0] — 2025-12-09 <a class="header-anchor" href="#_1-2-0-—-2025-12-09" aria-label="Permalink to &quot;[1.2.0] — 2025-12-09&quot;">​</a></h2><p>Published out of order; predates 0.1.1. Added the hotplug fix and the billing tracker. Not covered by <code>CHANGELOG.md</code>.</p><h2 id="_0-1-0-docs-—-unreleased-documentation-pass" tabindex="-1">[0.1.0-docs] — unreleased documentation pass <a class="header-anchor" href="#_0-1-0-docs-—-unreleased-documentation-pass" aria-label="Permalink to &quot;[0.1.0-docs] — unreleased documentation pass&quot;">​</a></h2><p>Comprehensive documentation improvements: <code>requirements.txt</code>, <code>ARCHITECTURE.md</code>, a troubleshooting section, a table of contents, expanded <code>SECURITY.md</code> and <code>CONTRIBUTING.md</code>, and the changelog itself.</p><h2 id="_0-1-0-—-initial-release" tabindex="-1">[0.1.0] — initial release <a class="header-anchor" href="#_0-1-0-—-initial-release" aria-label="Permalink to &quot;[0.1.0] — initial release&quot;">​</a></h2><p>CPU and RAM autoscaling, multi-host SSH support, Gotify and SMTP notifications, systemd integration, YAML configuration, host resource safety checks, scaling cooldowns.</p>',23)])])}const g=o(i,[["render",n]]);export{m as __pageData,g as default};
